for p in ppo_policy ppo_policy_v4; do
  /opt/sdnlab/bin/python -c "import numpy as n; d=n.load('ppo/$p.npz'); assert 'aW0' in d" || { echo "policy file $p damaged"; exit 1; }
done
chmod +x *.sh; chown -R "$U:$U" "$LAB"
MODELS="qwen2.5:3b qwen2.5:7b llama3.1:8b"
if [ "$PROFILE" = "llmbench" ] || [ "$PROFILE" = "govtest" ] || [ "$PROFILE" = "phase4b" ] || [ "$PROFILE" = "phase4c" ] || [ "$PROFILE" = "ctrl" ] || [ "$PROFILE" = "phase5" ] || [ "$PROFILE" = "phase5b" ] || [ "$PROFILE" = "v10" ] || [ "$PROFILE" = "v10s" ] || [ "$PROFILE" = "v10b" ] || [ "$PROFILE" = "final" ]; then
  if ! command -v ollama >/dev/null; then
    FREE=$(df --output=avail -BG / | tail -1 | tr -dc 0-9)
    if [ "$FREE" -lt 18 ]; then echo "!!! only ${FREE} GB free on the disk; ~15 GB are needed for Ollama + models"; exit 1; fi
    echo "== installing Ollama (one time)"; curl -fsSL https://ollama.com/install.sh | sh
  fi
  # the governor stands for a separate box: Ollama is pinned to 3 vCPUs (5-7) so the LLM cannot starve the testbed
  mkdir -p /etc/systemd/system/ollama.service.d
  printf '[Service]\nCPUAffinity=4 5 6 7\n' > /etc/systemd/system/ollama.service.d/cpu.conf
  systemctl daemon-reload; systemctl enable ollama >/dev/null 2>&1 || true; systemctl restart ollama
  if [ "$PROFILE" = "phase4b" ] && [ ! -f "$LAB/results_full/.phase4b_started" ] && ls -d "$LAB"/results_full/gov_qwen* >/dev/null 2>&1; then
    # LLM test runs made with the earlier settings are not part of the campaign
    OLD="$LAB/results_full/_govtest_old_$(date +%H%M)"; mkdir -p "$OLD"; mv "$LAB"/results_full/gov_qwen* "$OLD/"
  fi
  [ "$PROFILE" = "phase4b" ] && mkdir -p "$LAB/results_full" && touch "$LAB/results_full/.phase4b_started"
  if [ "$PROFILE" = "govtest" ] && ls -d "$LAB"/results_full/gov_* >/dev/null 2>&1; then
    OLD="$LAB/results_full/_govtest_old_$(date +%H%M)"; mkdir -p "$OLD"; mv "$LAB"/results_full/gov_* "$OLD/"
  fi
  for i in $(seq 1 30); do curl -s http://127.0.0.1:11434/api/tags >/dev/null && break; sleep 1; done
  for m in $MODELS; do
    ollama list | grep -q "^${m} " || { echo "== downloading model $m (one time)"; ollama pull "$m"; }
  done
fi
if [ "$PROFILE" = "llmbench" ]; then
  OUTB="$LAB/results_llmbench"; rm -rf "$OUTB"; mkdir -p "$OUTB"
  lscpu | grep -E "Model name|^CPU\(s\)" > "$OUTB/cpu.txt"; free -g >> "$OUTB/cpu.txt"
  for b in rulegov ollama:qwen2.5:3b ollama:qwen2.5:7b ollama:llama3.1:8b; do
    n=$(echo "$b" | tr ':/' '__')
    echo "== bench $b"
    /opt/sdnlab/bin/python gov_replay.py bench/flashcrowd bench/botnet --backend "$b" --repeat 2 \
      --out "$OUTB/$n.json" | grep -E "latency|valid_rate|precision|recall|block_clean|rejected" || true
  done
  tar czf "$H/results_llmbench.tgz" -C "$LAB" results_llmbench
  chown -R "$U:$U" "$LAB" "$H/results_llmbench.tgz"
  echo; echo "ALL DONE. Upload this file to the chat:  $H/results_llmbench.tgz"; ls -lh "$H/results_llmbench.tgz"
  exit 0
fi
if [ "$PROFILE" = "llmport2" ]; then
  # model self-test before the campaign: held-out benign interface states and flood-like states (see llmport.py)
  mkdir -p "$LAB/results_full"
  for m in qwen2.5:7b qwen2.5:3b; do
    echo "== self-test of the Swileh & Zhang prompt with $m"
    OLLAMA_URL=${GPU_OLLAMA_URL:-http://10.0.2.2:11434} LLMPORT_MODEL=$m /opt/sdnlab/bin/python baselines/llmport.py \
      --selftest baselines/llmport_selftest.json | tee -a "$LAB/results_full/llmport_selftest.txt"
  done
fi
echo "== v7.6 files installed in $LAB; starting campaign: $PROFILE"
mkdir -p "$LAB/results_full"; STAMP="$LAB/results_full/.start_${PROFILE}"; [ -f "$STAMP" ] || touch "$STAMP"
bash campaign.sh "$PROFILE"
RES=$(readlink -f results)
case "$PROFILE" in
  v10|v10s|v10b|final|scale)
    # only the runs of this campaign (results_full also holds every earlier run)
    (cd "$LAB" && find "$(basename "$RES")" -type f -newer "$STAMP" > /tmp/files_${PROFILE}.txt)
    tar czf "$H/results_${PROFILE}.tgz" -C "$LAB" -T /tmp/files_${PROFILE}.txt ;;
  *) tar czf "$H/results_${PROFILE}.tgz" -C "$LAB" "$(basename "$RES")" ;;
esac
chown -R "$U:$U" "$LAB" "$H/results_${PROFILE}.tgz"
echo; echo "ALL DONE. Upload this file to the chat:  $H/results_${PROFILE}.tgz"; ls -lh "$H/results_${PROFILE}.tgz"
